  const { window } = dom;

  // Polyfills
  window.Element.prototype.scrollIntoView = function () {};
  window.Element.prototype.scrollTo = function () {};

  function makeRect(left, top, width, height) {
    return { left, top, width, height, right: left + width, bottom: top + height, x: left, y: top };
  }

  window.Element.prototype.getBoundingClientRect = function () {
    if (this.style.display === 'none') return makeRect(0, 0, 0, 0);

    // Header and Nav Pills
    if (this.classList.contains('brand-container')) return makeRect(96, 24, 200, 48);
    if (this.classList.contains('nav-pill-item') || this.classList.contains('tab')) {
      const route = this.getAttribute('data-route');
      if (route === 'home') return makeRect(790, 28, 75, 40);
      if (route === 'movies') return makeRect(875, 28, 85, 40);
      if (route === 'series') return makeRect(970, 28, 80, 40);
      if (route === 'search') return makeRect(1060, 28, 80, 40);
    }

    // Hero buttons
    if (this.id === 'hero-play-btn') return makeRect(96, 420, 160, 52);
    if (this.id === 'hero-details-btn') return makeRect(276, 420, 160, 52);

    // Cards
    if (this.classList.contains('card-poster')) {
      const idx = parseInt(this.getAttribute('data-nav-index') || '0', 10);
      return makeRect(100 + idx * 240, 600, 220, 330);
    }
    if (this.classList.contains('card-episode')) {
      const idx = parseInt(this.getAttribute('data-nav-index') || '0', 10);
      return makeRect(100 + idx * 340, 700, 320, 180);
    }
    if (this.classList.contains('card-provider')) {
      const idx = parseInt(this.getAttribute('data-nav-index') || '0', 10);
      return makeRect(96 + idx * 100, 800, 72, 72);
    }

    // Virtual Keyboard
    if (this.classList.contains('key-btn')) {
      const row = parseInt(this.getAttribute('data-key-row') || '0', 10);
      const col = parseInt(this.getAttribute('data-key-col') || '0', 10);
      return makeRect(520 + col * 80, 220 + row * 72, 72, 64);
    }

    // Player OSD Controls
    if (this.id === 'player-back-btn') return makeRect(96, 54, 54, 54);
    if (this.id === 'osd-scrubber' || this.classList.contains('osd-progress-track')) return makeRect(240, 920, 1440, 12);
    if (this.classList.contains('osd-scrub-thumb')) return makeRect(240, 920, 24, 24);
    if (this.id === 'osd-play-btn' || this.classList.contains('btn-play-pause')) return makeRect(893, 953, 68, 68);
    if (this.id === 'osd-rewind-btn') return makeRect(815, 960, 54, 54);
