    if (this.id === 'osd-subtitles-btn') return makeRect(1420, 960, 180, 52);
    if (this.id === 'osd-server-btn') return makeRect(1616, 960, 180, 52);

    return makeRect(0, 0, 100, 40);
  };

  // Load scripts in correct dependency order
  const scripts = [
    'app/js/config.js',
    'app/js/navigation.js',
    'app/js/tmdb.js',
