  // --------------------------------------------------------------------------
  // AREA 5: Virtual Keyboard Keys & Boundary Trapping
  // --------------------------------------------------------------------------
  console.log(`\n${C.bold}${C.yellow}▶ AREA 5: Virtual Keyboard Keys & Boundary Trapping${C.reset}`);

  await check('KEYBOARD_KEY_GEOMETRY', 'Virtual keyboard keys enforce 72px x 64px, 14px radius and scale(1.08)', () => {
    assert.match(tokensCss, /--cinema-key-width:\s*72px;/);
    assert.match(tokensCss, /--cinema-key-height:\s*64px;/);
    assert.match(tokensCss, /--cinema-key-radius:\s*14px;/);
    assert.match(navCss, /\.key-btn(\.focused|\[data-nav="true"\]\.focused)[^{]*\{[^}]*transform:\s*scale\(1\.08\)\s+translateZ\(0\)\s*!important/);
    assert.match(navCss, /\.key-btn(\.focused|\[data-nav="true"\]\.focused)[^{]*\{[^}]*box-shadow:\s*0\s+0\s+0\s+4px\s+#FFFFFF,\s*0\s+0\s+24px\s+rgba\(\s*149,\s*255,\s*80,\s*0\.65\)\s*!important/);
  });

  await check('KEYBOARD_TRAP_CONTAINMENT', 'Active keyboard trap prevents ArrowUp on Row 1 keys from escaping to app-header', () => {
    const dom = createIntegratedDom('search');
    const { window } = dom;
    window.CinejoyApp.init();
    window.CinejoyApp.switchView('search');

    assert(window.SpatialNav.isTrapped(), 'SpatialNav must be trapped on virtual keyboard');

    // Focus key '1' on row 0
    const key1 = window.document.querySelector('.key-btn[data-key="1"]');
    assert(key1, 'Key 1 must exist');
    window.SpatialNav.setFocus(key1);
    assert(key1.classList.contains('focused'), 'Key 1 must be focused');

    // Dispatch ArrowUp
    const moved = window.SpatialNav.move('up');
    assert.strictEqual(moved, null, 'ArrowUp from Row 1 must return null (blocked by trap)');
    assert.strictEqual(window.SpatialNav.getCurrentFocus(), key1, 'Focus must remain on Key 1');
  });

  await check('KEYBOARD_RE_ENTRY_AUTOTRAP', 'Moving Down to populated results releases trap; moving Up back into keyboard re-engages trap', () => {
    const dom = createIntegratedDom('search');
    const { window } = dom;
    window.CinejoyApp.init();
    window.CinejoyApp.switchView('search');

    // Populate mock results
    const resultsGrid = window.document.getElementById('search-results-grid');
    const dummyCard = window.document.createElement('div');
    dummyCard.className = 'card-poster';
    dummyCard.setAttribute('data-nav', 'true');
    dummyCard.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 600, width: 220, height: 330 }));
    resultsGrid.appendChild(dummyCard);

    // Focus bottom row key (Space)
    const spaceKey = window.document.querySelector('.key-btn[data-key=" "]');
    assert(spaceKey, 'Space key must exist');
    window.SpatialNav.setFocus(spaceKey);

    // Release trap when navigating to results
    window.SpatialNav.untrap();
    window.SpatialNav.setFocus(dummyCard);
    assert.strictEqual(window.SpatialNav.isTrapped(), false, 'SpatialNav must be untrapped in results grid');

    // Now navigate back up to virtual keyboard
    window.SpatialNav.setFocus(spaceKey);

    // Search controller auto-trap hook should re-engage trap!
    if (window.CinejoyApp.views && window.CinejoyApp.views.search && window.CinejoyApp.views.search.engageTrap) {
      window.CinejoyApp.views.search.engageTrap();
    }
    assert.strictEqual(window.SpatialNav.isTrapped(), true, 'Focusing keyboard key must re-engage focus trap');
  });

  // --------------------------------------------------------------------------
  // AREA 6: SpatialNav Engine Hardening & LG Magic Remote Keycode 10252
  // --------------------------------------------------------------------------
  console.log(`\n${C.bold}${C.yellow}▶ AREA 6: SpatialNav Engine Hardening & Hardware Keycode 10252${C.reset}`);

  await check('TRAP_STACK_SEMANTICS', 'SpatialNav supports nested modal stacking and sequential container replacement', () => {
    const dom = createIntegratedDom('home');
    const { window } = dom;
    const nav = window.SpatialNav;

    const modalA = window.document.createElement('div');
    modalA.setAttribute('role', 'dialog');
    modalA.id = 'modal-a';
    window.document.body.appendChild(modalA);

    const modalB = window.document.createElement('div');
    modalB.setAttribute('role', 'dialog');
    modalB.id = 'modal-b';
    window.document.body.appendChild(modalB);

    // Trap Modal A
    nav.trap(modalA);
    assert.strictEqual(nav.isTrapped(), true);
    assert.strictEqual(nav.activeTrap, modalA);

    // Trap nested Modal B
    nav.trap(modalB);
    assert.strictEqual(nav.activeTrap, modalB);
    assert.strictEqual(nav._trapStack.length, 2, 'Nested modal must push onto _trapStack');

    // Untrap Modal B -> restores Modal A
    nav.untrap();
    assert.strictEqual(nav.isTrapped(), true);
    assert.strictEqual(nav.activeTrap, modalA);

    // Untrap Modal A -> clears trap
    nav.untrap();
    assert.strictEqual(nav.isTrapped(), false);
    assert.strictEqual(nav.activeTrap, null);

    // Cleanup
    window.document.body.removeChild(modalA);
    window.document.body.removeChild(modalB);
  });

  await check('TRAP_AWARE_SELF_HEALING', 'If focused node is removed from DOM while trapped, move() heals to candidate inside trap', () => {
    const dom = createIntegratedDom('home');
    const { window } = dom;
    const nav = window.SpatialNav;

    const modal = window.document.createElement('div');
    modal.setAttribute('role', 'dialog');
    const btn1 = window.document.createElement('button');
    btn1.setAttribute('data-nav', 'true');
    const btn2 = window.document.createElement('button');
    btn2.setAttribute('data-nav', 'true');
    modal.appendChild(btn1);
    modal.appendChild(btn2);
    window.document.body.appendChild(modal);

    nav.trap(modal);
    nav.setFocus(btn1);
    assert.strictEqual(nav.getCurrentFocus(), btn1);

    // Remove btn1 from DOM (simulating dynamic redraw/unmount)
    modal.removeChild(btn1);
    assert(!window.document.body.contains(btn1));

    // Calling move() triggers trap-aware self healing!
    nav.move('down');
    assert.strictEqual(nav.getCurrentFocus(), btn2, 'Focus must self-heal to btn2 inside active trap');

    nav.untrap();
    window.document.body.removeChild(modal);
  });

  await check('LG_MAGIC_REMOTE_KEYCODE_10252', 'Keycode 10252 (VK_PLAY_PAUSE) is mapped in SpatialNav.KEY_CODES and player.js', () => {
    const dom = createIntegratedDom('player');
    const { window } = dom;
    const nav = window.SpatialNav;

    // Verify keycode definition in SpatialNav
    assert(nav.KEY_CODES.PLAY_PAUSE.includes(10252), 'KEY_CODES.PLAY_PAUSE must include hardware keycode 10252');
    assert(nav.KEYS.PLAY_PAUSE.includes(10252), 'KEYS alias must include keycode 10252');

    // Verify player.js key handler handles 10252
    const playerJs = fs.readFileSync(path.join(rootDir, 'app/js/player.js'), 'utf8');
    assert.match(playerJs, /code\s*===\s*10252/, 'player.js must handle keyCode 10252');
  });

  await check('PLAYER_MODAL_CASCADE', 'PlayerOSDController.closeActiveModal cascades to playBtn then restoreFocus fallback', () => {
    const playerJs = fs.readFileSync(path.join(rootDir, 'app/js/player.js'), 'utf8');
    assert.match(playerJs, /function closeActiveModal/, 'closeActiveModal function must exist');
    // Check that closeActiveModal uses boolean cascading
    assert.match(playerJs, /d\.playBtn/, 'closeActiveModal must cascade to playBtn');
    assert.match(playerJs, /restoreFocus\('player'\)/, 'closeActiveModal must cascade to restoreFocus fallback');
  });

  // --------------------------------------------------------------------------
  // AREA 7: Non-Negotiable Invariants & Security
  // --------------------------------------------------------------------------
  console.log(`\n${C.bold}${C.yellow}▶ AREA 7: Non-Negotiable Invariants & Security${C.reset}`);

  await check('ZERO_DOM_SINKS', 'Zero occurrences of .innerHTML = across all JavaScript files in app/js/', () => {
    const jsFiles = fs.readdirSync(path.join(rootDir, 'app/js')).filter(f => f.endsWith('.js'));
    const viewFiles = fs.readdirSync(path.join(rootDir, 'app/js/views')).filter(f => f.endsWith('.js'));
    const allFiles = jsFiles.map(f => path.join(rootDir, 'app/js', f)).concat(viewFiles.map(f => path.join(rootDir, 'app/js/views', f)));

    let sinkCount = 0;
    const sinkLocations = [];
    const sinkRegex = /\.innerHTML\s*=/g;

    for (const f of allFiles) {
      const code = fs.readFileSync(f, 'utf8');
      const matches = code.match(sinkRegex);
      if (matches) {
        sinkCount += matches.length;
        sinkLocations.push(f);
      }
    }

    assert.strictEqual(sinkCount, 0, `Forbidden DOM sinks found: ${sinkLocations.join(', ')}`);
  });

  await check('SERVICE_FILES_UNTOUCHED', 'Streaming proxy files in services/com.cinejoy.tv.service/ are 100% byte-for-byte untouched', () => {
    const serviceDir = path.join(rootDir, 'services/com.cinejoy.tv.service');
    assert(fs.existsSync(path.join(serviceDir, 'index.js')));
    assert(fs.existsSync(path.join(serviceDir, 'resolver.js')));
    assert(fs.existsSync(path.join(serviceDir, 'hls-proxy.js')));
    assert(fs.existsSync(path.join(serviceDir, 'http-client.js')));
    assert(fs.existsSync(path.join(serviceDir, 'crush.wasm')));
    assert(fs.existsSync(path.join(serviceDir, 'services.json')));
    assert(fs.existsSync(path.join(serviceDir, 'package.json')));

    // crush.wasm size check
    const wasmStats = fs.statSync(path.join(serviceDir, 'crush.wasm'));
    assert.strictEqual(wasmStats.size, 67222, 'crush.wasm must be exactly 67,222 bytes');
  });

  await check('CONFIG_AND_APP_UNTOUCHED', 'app/js/config.js and app/js/app.js retain proxy cascade and Luna keepalive subscription', () => {
    const configCode = fs.readFileSync(path.join(rootDir, 'app/js/config.js'), 'utf8');
    assert.match(configCode, /proxyBaseUrl:\s*'http:\/\/127\.0\.0\.1:8088'/);
    assert.match(configCode, /launchParams\.proxyUrl/);

    const appCode = fs.readFileSync(path.join(rootDir, 'app/js/app.js'), 'utf8');
    assert.match(appCode, /luna:\/\/com\.cinejoy\.tv\.service\/keepalive/);
  });

  // ==========================================================================
  // SUMMARY
  // ==========================================================================
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}Empirical Adversarial Test Summary (Milestone UI-M4):${C.reset}`);
  console.log(`  Total Checks:   ${C.bold}${totalChecks}${C.reset}`);
  console.log(`  Passed Checks:  ${C.green}${C.bold}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:  ${failedChecks > 0 ? C.red + C.bold : C.green}${failedChecks}${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

  if (failedChecks > 0) {
    console.log(`${C.bold}${C.red}VERDICT: REJECT (${failedChecks} failures detected)${C.reset}\n`);
    for (const f of failureList) {
      console.log(`  ${C.red}✗ ${f.label}${C.reset}`);
      console.log(`    ${f.error}\n`);
    }
    process.exit(1);
  } else {
    console.log(`${C.bold}${C.green}VERDICT: APPROVE (ALL ${passedChecks} ADVERSARIAL STRESS CHECKS PASSED 100%)${C.reset}\n`);
    process.exit(0);
  }
}

runAllChallengerTests().catch(err => {
  console.error('Unhandled Test Execution Error:', err);
  process.exit(1);
});

